INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('2a306ef6-bdb3-45dd-a5fb-c64ad300b457', 'home', 'manifest', 'stat_2_desc', 'Winery in Amsterdam-Noord', 'Winery in Amsterdam-North', '2026-07-22T20:51:47.012Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('d47f2bd7-b75d-4409-9f71-d645b291610f', 'home', 'process', 'step_3_body', 'Hier krijgt de wijn zijn vorm. Staal, beton of amfora, ons eigen lab bewaakt elke stap van het proces, zodat elke wijn zijn eigen karakter krijgt.', 'Here the wine takes shape. Steel, concrete or amphora, our own lab oversees every step of the process, so each wine develops its own character.', '2026-07-22T19:00:19.835Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('4d7373fb-4f97-46fb-a7ec-724df0849fb8', 'home', 'process', 'step_1_title', 'De druif', 'The grape', '2026-07-22T19:00:19.838Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('47526db8-ce20-47cf-8ec8-a6714e022247', 'home', 'process', 'heading_em', 'dwars door de stad.', 'straight through the city.', '2026-07-22T19:00:19.843Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('b3a0f45a-0484-482b-ac08-91a2b29602fb', 'home', 'process', 'heading_lead', 'Van boer tot fles, ', 'From farmer to bottle, ', '2026-07-22T19:00:19.845Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('b3ecc44c-1769-40b8-b2c0-00e86e1a5f2c', 'home', 'process', 'sub_text', 'Wij verplaatsen de druif, niet de wijn. Daardoor kan je hier van dichtbij mee maken hoe wijn écht gemaakt wordt.', 'We move the grape, not the wine. This lets you experience close-up how wine is truly made.', '2026-07-22T19:00:19.846Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('03098a05-cb2b-4273-9a0a-15d356fd5172', 'home', 'process', 'step_3_title', 'De winery', 'The winery', '2026-07-22T19:00:19.847Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('36593da2-d4cd-425b-8337-ad547a0a1bd3', 'home', 'process', 'step_4_title', 'De fles', 'The bottle', '2026-07-22T19:00:19.848Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('65ec74ee-7303-47bb-92fc-25d4b99fbba1', 'home', 'process', 'step_1_body', 'Alles begint bij de druif. We werken met een select netwerk van wijnboeren uit heel Europa, die stuk voor stuk biologisch telen en met de hand oogsten op het juiste moment.', 'It all begins with the grape. We work with a select network of farmers from all across Europe, each of them growing organically and harvesting by hand at exactly the right moment.', '2026-07-22T19:00:19.828Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('090b8503-6d71-435c-a71d-b41ee966d07b', 'home', 'paths', 'path_1_title', 'Tour & tastings', 'Tour & tastings', '2026-07-22T19:41:05.921Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('843a22de-2455-46f7-b2c2-7ff459382350', 'home', 'process', 'step_2_title', 'De reis', 'The journey', '2026-07-22T19:00:19.840Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('8b452cc2-2752-407c-9242-1c6de2e76a2f', 'home', 'paths', 'path_2_title', 'Voor bedrijven & horeca', 'For businesses & hospitality', '2026-07-22T19:41:05.923Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('1455118f-636b-4285-884e-4de04b60b255', 'home', 'process', 'step_4_body', 'De laatste stap is de fles. Hier komt alles samen: de druif, de reis en de ambacht in de winery. Nu is de wijn klaar om van genoten te worden. ', 'The last step is the bottle. That''s where everything comes together: the grape, the journey, and the craft from the winery. Now the wine is ready to be enjoyed.', '2026-07-22T19:00:19.842Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('efb6ecb2-2084-4e7f-9e25-da4ff96ad756', 'home', 'paths', 'intro_body', 'Toerist, inkoper of liefhebber: iedereen drinkt hier dezelfde wijn. Alleen de weg ernaartoe verschilt.', 'Tourist, buyer, or wine lover: everyone here drinks the same wine. Only the path there differs.', '2026-07-22T19:41:05.924Z', NULL) ON CONFLICT DO NOTHING;
