INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('269c108b-2072-493b-a711-b7d7f97f11f0', 'home', 'paths', 'path_3_body', 'De volledige collectie, thuisbezorgd. Van klassieke monocépages tot blends die alleen in Amsterdam-Noord konden ontstaan.', 'The complete collection, delivered to your door. From classic single-varietals to blends that could only exist in Amsterdam-North.', '2026-07-22T19:41:05.926Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('259fd196-afe3-4ea2-8929-a96c6d369fc8', 'home', 'paths', 'path_1_body', '70 minuten tussen de tanks, zes wijnen op tafel, luisterend naar verhalen over het wijn maken. Voor bezoekers van de stad, vriendengroepen en iedereen die wil weten hoe stadswijn smaakt.', '70 minutes between the tanks, six wines on the table, complete with stories about our love for winemaking. For city visitors, groups of friends, and anyone who wants to know how urban wine tastes.', '2026-07-22T19:41:05.927Z', NULL) ON CONFLICT DO NOTHING;
