INSERT INTO "content_blocks" ("id", "page", "section", "field_key", "value_nl", "value_en", "updated_at", "updated_by") VALUES ('83cd147c-3e53-49a0-8392-c7dfc13c599c', 'home', 'process', 'step_2_body', 'Elke druif reist gekoeld van de boer naar Amsterdam. Het klinkt als transport, maar het is eigenlijk al het begin van de wijn: op de snelweg gebeuren de eerste stappen van de fermentatie.', 'Every grape travels chilled from the farmer to Amsterdam. It sounds like transport, but it’s actually already the beginning of the wine: the first steps of fermentation happen right there on the highway.', '2026-07-22T19:00:19.850Z', NULL) ON CONFLICT DO NOTHING;
