INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('cde21bec-2663-4a89-b0cb-9ee572c5a732', 'home', 'footer', '{"do_link_2":{"valueEn":"For businesses","valueNl":"Voor bedrijven"},"do_heading":{"valueEn":"Do","valueNl":"Doen"},"footer_note":{"valueEn":"Urban winery on the IJ. Grapes from all over Europe, but wine from Amsterdam-North, since 2017.","valueNl":"Urban winery aan het IJ. Druiven uit heel Europa, maar wijn uit Amsterdam-Noord, sinds 2017."},"discover_link_1":{"valueEn":"Our story","valueNl":"Het verhaal"},"discover_link_2":{"valueEn":"The process","valueNl":"Het proces"},"discover_link_3":{"valueEn":"The collection","valueNl":"De collectie"},"discover_heading":{"valueEn":"Discover","valueNl":"Ontdek"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.241Z') ON CONFLICT DO NOTHING;
