INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('56bdb489-6997-4d1c-bb5c-0ca27ad3f9b0', 'home', 'hero', '{"intro_em":{"valueEn":"No vineyard, no problem.","valueNl":"Geen wijngaard, geen probleem."},"eyebrow_3":{"valueEn":"Wine from the city, for the city","valueNl":"Wijn uit de stad, voor de stad"},"intro_lead":{"valueEn":"Grapes from all over Europe, brought together in Amsterdam-North. ","valueNl":"Druiven uit heel Europa, samengebracht in Amsterdam-Noord. "},"cta_primary":{"valueEn":"Tour & Tasting","valueNl":"Tour & Tasting"},"cta_secondary":{"valueEn":"For businesses","valueNl":"Zakelijk"},"media_caption":{"valueEn":"↳ The winery, Johan van Hasseltweg 51 Amsterdam-Noord","valueNl":"↳ De winery, Johan van Hasseltweg 51, Amsterdam Noord"},"hero_image_url":{"valueEn":"/assets/hero-winery.jpg","valueNl":"/assets/hero-winery.jpg"},"script_tagline":{"valueEn":"the urban winery","valueNl":"de urban winery"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.277Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('0134fdb9-02d5-424e-8602-553b288dc852', 'home', 'manifest', '{"label":{"valueEn":"Our story","valueNl":"Het verhaal"},"body_lead":{"valueEn":"Since 2017, grapes from all over Europe travel chilled to Amsterdam-North. ","valueNl":"Sinds 2017 reizen druiven uit heel Europa gekoeld naar Amsterdam-Noord. "},"body_tail":{"valueEn":"With the city of Amsterdam as our \"vineyard\", we are more free than any classic wineproducer. Riesling meeting Moscatel? Here it''s possible.","valueNl":"Met de stad Amsterdam als onze \"wijngaard\", zijn we vrijer dan elke klassieke wijnproducent. Riesling die Moscatel ontmoet? Bij ons kan het."},"body_strong":{"valueEn":"To ripe in steel tanks, concrete tanks, amphora, and oak barrels. ","valueNl":"Om in stalen tanks, betonnen tanks, amfora en eikenhouten vaten te rijpen. "},"stat_1_desc":{"valueEn":"Decanter points","valueNl":"Decanter punten"},"stat_2_desc":{"valueEn":"Winery in Amsterdam-North","valueNl":"Winery in Amsterdam-Noord"},"stat_3_desc":{"valueEn":"Countries where our grapes grow","valueNl":"Landen waar onze druiven groeien"},"stat_4_desc":{"valueEn":"Bottles per year","valueNl":"Flessen per jaar"},"stat_1_value":{"valueEn":"91","valueNl":"91"},"stat_2_value":{"valueEn":"1000","valueNl":"1000"},"stat_3_value":{"valueEn":"5","valueNl":"5"},"stat_4_value":{"valueEn":"200000","valueNl":"200000"},"heading_line1":{"valueEn":"No vineyard.","valueNl":"Geen wijngaard."},"heading_line2":{"valueEn":"No problem.","valueNl":"Geen probleem."}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.297Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('c8a07a86-3724-4639-b585-4ee7e59147ad', 'home', 'marquee', '{"marquee_1":{"valueEn":"First urban winery in the Netherlands","valueNl":"Eerste urban winery van Nederland"},"marquee_2":{"valueEn":"The largest in Europe","valueNl":"De grootste van Europa"},"marquee_3":{"valueEn":"Grapes from all over Europe","valueNl":"Druiven uit heel Europa"},"marquee_4":{"valueEn":"Tastings among the tanks","valueNl":"Proeven tussen de tanks"},"marquee_5":{"valueEn":"Private labels","valueNl":"Private labels"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.316Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('9518d55e-7b9e-41c4-85fe-95747599a027', 'home', 'paths', '{"label":{"valueEn":"Choose your glass","valueNl":"Kies je glas"},"intro_body":{"valueEn":"Tourist, buyer, or wine lover: everyone here drinks the same wine. Only the path there differs.","valueNl":"Toerist, inkoper of liefhebber: iedereen drinkt hier dezelfde wijn. Alleen de weg ernaartoe verschilt."},"path_1_body":{"valueEn":"70 minutes between the tanks, six wines on the table, complete with stories about our love for winemaking. For city visitors, groups of friends, and anyone who wants to know how urban wine tastes.","valueNl":"70 minuten tussen de tanks, zes wijnen op tafel, luisterend naar verhalen over het wijn maken. Voor bezoekers van de stad, vriendengroepen en iedereen die wil weten hoe stadswijn smaakt."},"path_2_body":{"valueEn":"Bulk orders, private label, corporate gifts, and events in the winery. A single point of contact, volume discounts, produced 10 minutes from Central Station.","valueNl":"Grote afname, private label, relatiegeschenken en events in de winery. Eén aanspreekpunt, scherpe staffels, geproduceerd op 10 minuten van CS."},"path_3_body":{"valueEn":"The complete collection, delivered to your door. From classic single-varietals to blends that could only exist in Amsterdam-North.","valueNl":"De volledige collectie, thuisbezorgd. Van klassieke monocépages tot blends die alleen in Amsterdam-Noord konden ontstaan."},"path_1_title":{"valueEn":"Tour & tastings","valueNl":"Tour & tastings"},"path_2_title":{"valueEn":"For businesses & hospitality","valueNl":"Voor bedrijven & horeca"},"path_3_title":{"valueEn":"The webshop","valueNl":"De webshop"},"heading_line1":{"valueEn":"For tasters, pourers","valueNl":"Voor proevers, schenkers"},"heading_line2_em":{"valueEn":"home drinkers.","valueNl":"thuisdrinkers."}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.335Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('1536ce7b-44f3-407c-9c79-d400c2df8779', 'home', 'place', '{"label":{"valueEn":"The venue","valueNl":"De plek"},"cta_label":{"valueEn":"Plan your visit","valueNl":"Plan je bezoek"},"hours_line1":{"valueEn":"Tues to Fri // Saturday","valueNl":"Di tot vrij // Zaterdag"},"hours_line2":{"valueEn":"10 to 5 // 12 to 6","valueNl":"10 tot 17 // 12 tot 18"},"route_line1":{"valueEn":"Ferry from Central Station, 10 min bike","valueNl":"Pont vanaf CS, 10 min fietsen"},"route_line2":{"valueEn":"or metro 52 → Noorderpark","valueNl":"of metro 52 → Noorderpark"},"address_line1":{"valueEn":"Johan van Hasseltweg 51","valueNl":"Johan van Hasseltweg 51"},"address_line2":{"valueEn":"Amsterdam-North","valueNl":"Amsterdam-Noord"},"heading_line1":{"valueEn":"A winery","valueNl":"Een winery"},"heading_line2":{"valueEn":"in the city","valueNl":"in de stad"},"hours_heading":{"valueEn":"Hours (shop)","valueNl":"Open (winkel)"},"address_heading":{"valueEn":"Address","valueNl":"Adres"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.358Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('a735410e-45e1-4a90-ab3b-7fd2a6137bc1', 'home', 'process', '{"sub_text":{"valueEn":"We move the grape, not the wine. This lets you experience close-up how wine is truly made.","valueNl":"Wij verplaatsen de druif, niet de wijn. Daardoor kan je hier van dichtbij mee maken hoe wijn écht gemaakt wordt."},"heading_em":{"valueEn":"straight through the city.","valueNl":"dwars door de stad."},"step_1_body":{"valueEn":"It all begins with the grape. We work with a select network of farmers from all across Europe, each of them growing organically and harvesting by hand at exactly the right moment.","valueNl":"Alles begint bij de druif. We werken met een select netwerk van wijnboeren uit heel Europa, die stuk voor stuk biologisch telen en met de hand oogsten op het juiste moment."},"step_2_body":{"valueEn":"Every grape travels chilled from the farmer to Amsterdam. It sounds like transport, but it’s actually already the beginning of the wine: the first steps of fermentation happen right there on the highway.","valueNl":"Elke druif reist gekoeld van de boer naar Amsterdam. Het klinkt als transport, maar het is eigenlijk al het begin van de wijn: op de snelweg gebeuren de eerste stappen van de fermentatie."},"step_3_body":{"valueEn":"Here the wine takes shape. Steel, concrete or amphora, our own lab oversees every step of the process, so each wine develops its own character.","valueNl":"Hier krijgt de wijn zijn vorm. Staal, beton of amfora, ons eigen lab bewaakt elke stap van het proces, zodat elke wijn zijn eigen karakter krijgt."},"step_4_body":{"valueEn":"The last step is the bottle. That''s where everything comes together: the grape, the journey, and the craft from the winery. Now the wine is ready to be enjoyed.","valueNl":"De laatste stap is de fles. Hier komt alles samen: de druif, de reis en de ambacht in de winery. Nu is de wijn klaar om van genoten te worden. "},"heading_lead":{"valueEn":"From farmer to bottle, ","valueNl":"Van boer tot fles, "},"step_1_title":{"valueEn":"The grape","valueNl":"De druif"},"step_2_title":{"valueEn":"The journey","valueNl":"De reis"},"step_3_title":{"valueEn":"The winery","valueNl":"De winery"},"step_4_title":{"valueEn":"The bottle","valueNl":"De fles"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.378Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('5937a5ad-c434-4ebc-89a7-0a34d9679f93', 'home', 'wines', '{"label":{"valueEn":"The collection","valueNl":"De collectie"},"cta_label":{"valueEn":"Shop all wines","valueNl":"Shop alle wijnen"},"heading_line1":{"valueEn":"From classic","valueNl":"Van klassiek"},"heading_line2_em":{"valueEn":"rebellious.","valueNl":"eigenwijs."},"heading_line2_lead":{"valueEn":"to ","valueNl":"tot "}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.398Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('30862339-b123-4d9f-85eb-5f8db5410044', 'tours-tastings', 'main', '{"hero_sub":{"valueEn":"70 minutes between the tanks. Six wines on the table. Experience it yourself, instead of just reading about it.","valueNl":"70 minuten tussen de tanks. Zes wijnen op tafel. Ervaar het zelf, in plaats van er over te lezen."},"tour_body":{"valueEn":"A 70-minute tour through the winery. Learn how grapes become wine, from farmer to bottle, and hear the story behind Chateau Amsterdam.","valueNl":"Een tour van 70 minuten door de winery. Je leert hoe druiven worden verwerkt tot wijn, van boer tot fles, en hoort het verhaal achter Chateau Amsterdam."},"hero_label":{"valueEn":"Discover Chateau","valueNl":"Ontdek Chateau"},"reserve_sub":{"valueEn":"We confirm your request personally.","valueNl":"We bevestigen je aanvraag persoonlijk."},"strip_price":{"valueEn":"€55","valueNl":"€55"},"strip_wines":{"valueEn":"6","valueNl":"6"},"tasting_body":{"valueEn":"During the tour you taste 6 wines. Alcoholfree options? Let us know in your request and we''ll take care of it.","valueNl":"Tijdens de tour proef je 6 wijnen. Drinkt er iemand geen alcohol? Laat het weten bij je aanvraag, dan houden we er rekening mee."},"tour_heading":{"valueEn":"Between the tanks","valueNl":"Tussen de tanks"},"hero_title_em":{"valueEn":"tasting","valueNl":"tasting"},"opening_line1":{"valueEn":"In the middle of the city, we make wine, from tank to glass.","valueNl":"Midden in de stad wordt er wijn gemaakt, van tank tot glas."},"opening_line2":{"valueEn":"Come see, how city wine tastes.","valueNl":"Kom kijken, hoe stadswijn smaakt."},"reserve_label":{"valueEn":"Reserve","valueNl":"Reserveren"},"hero_photo_url":{"valueEn":"/assets/tasting-hero.jpg#35p27p","valueNl":"/assets/tasting-hero.jpg#35p27p"},"strip_discount":{"valueEn":"20%","valueNl":"20%"},"strip_duration":{"valueEn":"70 min","valueNl":"70 min"},"hero_title_lead":{"valueEn":"Tour &","valueNl":"Tour &"},"reserve_heading":{"valueEn":"Book your spot between the tanks.","valueNl":"Boek je plek tussen de tanks."},"tasting_heading":{"valueEn":"Six wines, one table","valueNl":"Zes wijnen, één tafel"},"reserve_photo_url":{"valueEn":"/assets/place-map.jpg#48p49p","valueNl":"/assets/place-map.jpg#48p49p"},"strip_price_label":{"valueEn":"Per person","valueNl":"Per persoon"},"strip_wines_label":{"valueEn":"Wines to taste","valueNl":"Wijnen om te proeven"},"tour_main_photo_url":{"valueEn":"/assets/step-makerij.jpg","valueNl":"/assets/step-makerij.jpg"},"strip_discount_label":{"valueEn":"Discount in the shop","valueNl":"Korting in de winkel"},"strip_duration_label":{"valueEn":"Tour & tasting together","valueNl":"Tour & tasting samen"},"tour_detail_photo_url":{"valueEn":"/assets/step-druif.jpg","valueNl":"/assets/step-druif.jpg"},"tasting_main_photo_url":{"valueEn":"/assets/path-taste.jpg","valueNl":"/assets/path-taste.jpg"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.417Z') ON CONFLICT DO NOTHING;
INSERT INTO "content_versions" ("id", "page", "section", "snapshot", "note", "updated_by", "created_at") VALUES ('63c8d8bd-79fd-42db-bb8f-155d4f48b413', 'voor-bedrijven', 'main', '{"form_note":{"valueEn":"We''ll get back to you quickly.","valueNl":"We nemen snel contact met je op."},"form_intro":{"valueEn":"One form, straight to our team.","valueNl":"Eén formulier, rechtstreeks naar ons team."},"form_label":{"valueEn":"Request","valueNl":"Aanvraag"},"intro_body":{"valueEn":"From a drink between the tanks to your own name on the bottle. One partner, ten minutes from Amsterdam Central Station. Choose below what you’re thinking of, we’ll take it from there.","valueNl":"Van een borrel tussen de tanks tot je eigen naam op de fles. Eén partner, tien minuten van Amsterdam CS. Kies hieronder waar je aan denkt, wij nemen het van daar over. "},"index_label":{"valueEn":"Four services, one point of contact","valueNl":"Vier diensten, één aanspreekpunt"},"intro_label":{"valueEn":"Business & hospitality","valueNl":"Zakelijk & horeca"},"form_heading":{"valueEn":"Tell us what you have in mind.","valueNl":"Vertel ons waar je aan denkt."},"service_1_body":{"valueEn":"Have drinks with your team between the tanks. From 10 to 60 guests, with or without bites.","valueNl":"Borrel met je team tussen de wijntanks. Van 10 tot 60 personen, met of zonder bites erbij."},"service_2_body":{"valueEn":"Your name on the bottle. We vinify, you decide the label and the story behind it.","valueNl":"Jullie naam op de fles. Wij vinifiëren, jij bepaalt het etiket en het verhaal erachter."},"service_3_body":{"valueEn":"The winery as your private setting? 20 to 150 guests, including bar, sound and atmosphere.","valueNl":"Jouw eigen winery voor een avond? 20 tot 150 gasten, inclusief bar, geluid en sfeer."},"service_4_body":{"valueEn":"More and more hospitality venues pour our wine, not just in Amsterdam. We deliver, wherever you are. A reliable partner, without middlemen.","valueNl":"Steeds meer horeca schenkt onze wijn, niet alleen in Amsterdam. Wij leveren, waar jij zit. Een betrouwbare partner, zonder tussenpartijen."},"strip_distance":{"valueEn":"10 min","valueNl":"10 min"},"intro_photo_url":{"valueEn":"/assets/path-pour.jpg","valueNl":"/assets/path-pour.jpg"},"service_1_title":{"valueEn":"Tastings & drinks","valueNl":"Tastings & borrels"},"service_2_title":{"valueEn":"Private label & corporate gifts","valueNl":"Private label & relatiegeschenken"},"service_3_title":{"valueEn":"Events & venue rental","valueNl":"Events & locatieverhuur"},"service_4_title":{"valueEn":"Wholesale for hospitality","valueNl":"Groothandel voor horeca"},"intro_heading_em":{"valueEn":"for your business","valueNl":"op jouw manier"},"intro_heading_lead":{"valueEn":"Wine that works","valueNl":"Wijn voor jouw bedrijf"},"strip_contact_label":{"valueEn":"One point of contact, from start to delivery","valueNl":"Eén aanspreekpunt, van begin tot levering"},"strip_distance_label":{"valueEn":"From Amsterdam Central, in the heart of Noord","valueNl":"Van Amsterdam CS, midden in Noord"},"strip_produced_label":{"valueEn":"Produced in our own winery","valueNl":"Geproduceerd in de eigen winery"}}'::jsonb, 'Officiële baseline (22 aug 2026)', NULL, '2026-08-22T09:42:17.435Z') ON CONFLICT DO NOTHING;
